  `logistics_points` int NULL DEFAULT 0 COMMENT '物流点数',
  `tb_business` tinyint(1) NULL DEFAULT 1 COMMENT '淘宝业务',
  `assigned_business` tinyint(1) NULL DEFAULT 0 COMMENT '指派业务',
  `compensation` tinyint(1) NULL DEFAULT 0,
  `commission_discount_rate` decimal(10, 2) NULL DEFAULT 1.00 COMMENT '佣金折率',
