  `order_num` int NULL DEFAULT 0,
  `white_list` tinyint(1) NULL DEFAULT NULL,
  `close_rebate` tinyint(1) NULL DEFAULT 0,
  `commission_rebate_limit` decimal(10, 2) NULL DEFAULT 0.00,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `username`(`user_name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商家' ROW_FORMAT = DYNAMIC;

