-- ----------------------------
-- Table structure for express_flow
-- ----------------------------
DROP TABLE IF EXISTS `express_flow`;
CREATE TABLE `express_flow`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `store_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '仓库名称',
  `store_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仓库ID',
  `sheet_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '面单ID',
  `store_price` decimal(10, 2) NOT NULL COMMENT '快递(面单)价格',
  `gift_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '礼品名称',
  `gift_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '礼品ID',
  `flow_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快递名称',
  `gift_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '礼品图片',
  `gift_price` decimal(10, 2) NOT NULL COMMENT '礼品价格',
  `express_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快递编号',
  `express_type` int NULL DEFAULT NULL COMMENT '面单类型 1=通用面单 2=菜鸟面单 3=拼多多面单 4=京东面单 5=抖音面单',
  `store_index` int NULL DEFAULT NULL COMMENT '仓库index',
  `gift_index` int NULL DEFAULT NULL COMMENT '礼品index',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '礼品代发:仓库/礼品本地缓存(每日全量重建)' ROW_FORMAT = DYNAMIC;

