-- ----------------------------
-- Table structure for flag_channel_config
-- ----------------------------
DROP TABLE IF EXISTS `flag_channel_config`;
CREATE TABLE `flag_channel_config`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform` int NOT NULL COMMENT '平台码,对齐 store.type:1淘宝 2京东 3拼多多 4抖音 5阿里巴巴',
  `platform_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台展示名',
  `enabled` int NOT NULL DEFAULT 0 COMMENT '是否开放插旗(0关 1开)',
  `endpoint` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '上游插旗接口路径,必须 /api/ 开头',
  `query_endpoint` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '上游验key接口路径(绑定时校验key、取授权有效期)',
  `flags` json NOT NULL COMMENT '旗帜列表 JSON:[{\"value\":数字,\"name\":\"旗帜名\",\"color\":\"#颜色\"}]',
  `purchase_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '该平台订购地址',
  `tutorial` json NULL COMMENT '购买授权图文教程 JSON:[{\"title\":\"步骤标题\",\"imageUrl\":\"图片地址\"}],顺序即步骤顺序',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `flag_channel_config_platform_key`(`platform` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '插旗渠道配置(按店铺平台:是否开放/上游接口/旗帜/订购地址)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of flag_channel_config
-- ----------------------------

