  `flow_text` json NULL COMMENT '上游返回原文',
  `type` int NULL DEFAULT NULL COMMENT '0=礼品下单,1=礼品支付,2=插旗',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type`(`type` ASC) USING BTREE,
  INDEX `flow_id`(`flow_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '礼品代发:礼品操作日志' ROW_FORMAT = DYNAMIC;

