-- ----------------------------
-- Table structure for gift_shipping_order_number
-- ----------------------------
DROP TABLE IF EXISTS `gift_shipping_order_number`;
CREATE TABLE `gift_shipping_order_number`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_order_id` int NOT NULL DEFAULT 0 COMMENT '订单ID,对应sub_task.id',
  `business_id` int NOT NULL DEFAULT 0 COMMENT '该订单商家ID',
  `task_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '订单任务编号',
  `order_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '订单编号',
  `third_order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '第三方平台订单ID(买手提交的真实订单号)',
  `order_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上游礼品网订单号',
  `delivery_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '快递单号',
  `delivery_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '快递code',
  `wwid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺旺旺ID',
  `type` int NULL DEFAULT NULL COMMENT '1=淘宝',
  `execute_number` int NULL DEFAULT 0 COMMENT '执行/重试次数',
  `order_status` int NULL DEFAULT NULL COMMENT '0=出单失败,1=待出单,2=出单成功,3=插旗失败,4=插旗成功,5=已退款',
  `express_type` int NULL DEFAULT NULL COMMENT '面单类型 1=通用面单 2=菜鸟面单 3=拼多多面单 4=京东面单 5=抖音面单',
  `store_id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仓库id',
  `good_id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '礼品ID',
  `detail_data` json NULL COMMENT '礼品详细信息(名称/价格/重量等)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `delivery_sn`(`delivery_sn` ASC) USING BTREE,
  INDEX `task_order_id`(`task_order_id` ASC) USING BTREE,
  INDEX `business_id`(`business_id` ASC) USING BTREE,
  INDEX `order_number`(`order_number` ASC) USING BTREE,
  INDEX `task_number`(`task_number` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '礼品发货订单列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of gift_shipping_order_number
-- ----------------------------

