  `amount_received` decimal(10, 2) NULL DEFAULT NULL COMMENT '到账金额',
  `task_id` int NULL DEFAULT NULL COMMENT '任务id',
  `task_type` int NULL DEFAULT NULL COMMENT '任务类型',
  `task_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务编号',
  `order_id` int NULL DEFAULT NULL COMMENT '订单id',
  `order_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单编号',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `as_type` int NULL DEFAULT NULL COMMENT '增减类型 1增加 2减少',
  `system_trading_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `administrator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `account_type` int NULL DEFAULT NULL COMMENT '账户类型',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`system_trading_number` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '业务员 资金变动明细' ROW_FORMAT = DYNAMIC;

