  `platform_order_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `platform_goods_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `positive_feedback_type` int NULL DEFAULT NULL,
  `receive_time` timestamp NULL DEFAULT NULL,
  `review_complete_date` date NULL DEFAULT NULL,
  `review_time` timestamp NULL DEFAULT NULL,
  `verify_time` timestamp NULL DEFAULT NULL,
  `review_status` int NULL DEFAULT NULL,
  `cancel_times` int NULL DEFAULT 0,
  `verify_store_name_time` timestamp NULL DEFAULT NULL,
  `browse_time` timestamp NULL DEFAULT NULL,
  `browsed_submit_time` timestamp NULL DEFAULT NULL,
  `browsed` tinyint(1) NULL DEFAULT 0,
  `business_return` tinyint(1) NULL DEFAULT NULL,
  `status` int NOT NULL,
  `urgent_review` tinyint(1) NULL DEFAULT NULL,
  `actual_payment_amount` decimal(10, 2) NULL DEFAULT NULL,
  `order_submit_time` timestamp NULL DEFAULT NULL,
  `order_submit_time_format` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `has_relate_products` tinyint NULL DEFAULT NULL,
  `complete_time` timestamp NULL DEFAULT NULL,
  `principal_repayment_time` timestamp NULL DEFAULT NULL,
  `principal_repayment_status` int NULL DEFAULT 1,
  `commission_repayment_state` tinyint(1) NULL DEFAULT 0,
  `commission_repayment_time` timestamp NULL DEFAULT NULL,
  `commission_repayment_date` date NULL DEFAULT NULL,
  `commission` decimal(10, 2) NULL DEFAULT 0.00,
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `principal_repayment_remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `review_complete_time` timestamp NULL DEFAULT NULL,
  `review_remark` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `review_charge` decimal(10, 2) NULL DEFAULT 0.00,
  `review_commission` decimal(10, 2) NULL DEFAULT 0.00,
  `service_info` json NULL,
  `return_type` int NULL DEFAULT NULL,
  `settled` tinyint(1) NULL DEFAULT 0,
  `evaluate_time` timestamp NULL DEFAULT NULL,
  `generate_bills` tinyint(1) NULL DEFAULT 0,
  `review_submit_time` timestamp NULL DEFAULT NULL,
  `delivery_time` timestamp NULL DEFAULT NULL,
  `positive_feedback_type_service_charge` decimal(10, 2) NULL DEFAULT NULL,
  `fee` decimal(10, 2) NULL DEFAULT NULL,
  `review_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_results` int NULL DEFAULT 0,
  `value_added_service_charge` decimal(10, 2) NULL DEFAULT NULL,
  `urgent_review_time` timestamp NULL DEFAULT NULL,
  `cancel_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `station` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `station_id` int NULL DEFAULT NULL,
  `show_service_charge` decimal(10, 2) NULL DEFAULT NULL,
  `positive_feedback_type_commission` decimal(10, 2) NULL DEFAULT NULL,
  `value_added_commission` decimal(10, 2) NULL DEFAULT NULL,
  `cost_service_charge` decimal(10, 2) NULL DEFAULT NULL,
  `taobao_verification` tinyint(1) NULL DEFAULT 0,
  `taobao_flag` int NULL DEFAULT 0,
  `postpose_positive_feedback_type_service_charge` decimal(10, 2) NULL DEFAULT 0.00,
  `postpose_positive_feedback_type_commission` decimal(10, 2) UNSIGNED ZEROFILL NULL DEFAULT 00000000.00,
  `postpose_positive_feedback_type_commission_repayment_state` tinyint(1) NULL DEFAULT 0,
  `postpose_positive_feedback_type_commission_repayment` datetime NULL DEFAULT NULL,
  `postpose_positive_feedback_type_commission_repayment_date` date NULL DEFAULT NULL,
  `bounty` int NULL DEFAULT NULL,
  `evaluate_reject_times` int NULL DEFAULT 0,
  `paused` tinyint(1) NULL DEFAULT 0,
  `evaluate_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `evaluate_code_verify` tinyint(1) NULL DEFAULT 0,
  `date` date NULL DEFAULT NULL,
  `order_reject_times` int NULL DEFAULT NULL,
  `bill_settled` tinyint(1) NULL DEFAULT 0,
  `taobao_flag_time` timestamp NULL DEFAULT NULL,
  `taobao_flag_fail` int NULL DEFAULT 0,
  `taobao_flag_fail_msg` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `uid`(`user_id` ASC) USING BTREE,
  INDEX `status`(`status` ASC) USING BTREE,
  INDEX `business_id`(`business_id` ASC) USING BTREE,
  INDEX `taskid`(`task_id` ASC) USING BTREE,
  INDEX `taskid-status`(`task_id` ASC, `status` ASC) USING BTREE,
  INDEX `businessid-status`(`business_id` ASC, `status` ASC) USING BTREE,
  INDEX `rev`(`review_status` ASC, `status` ASC, `review_complete_time` ASC) USING BTREE,
  INDEX `platform_order_id`(`platform_order_id` ASC) USING BTREE,
  INDEX `rsu`(`return_type` ASC, `status` ASC, `user_id` ASC) USING BTREE,
  INDEX `ps`(`postpose_positive_feedback_type_commission_repayment_state` ASC, `status` ASC) USING BTREE,
  INDEX `user_status`(`user_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单' ROW_FORMAT = DYNAMIC;

