  `enable_service` json NULL,
  `api_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `app_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `app_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `merchants_voice_inform_price` decimal(10, 2) NULL DEFAULT NULL,
  `automatic_query` tinyint(1) NULL DEFAULT NULL,
  `down_right_query_price` decimal(10, 2) NULL DEFAULT NULL,
  `orders_query_price` decimal(10, 2) NULL DEFAULT NULL,
  `marking_prices` decimal(10, 2) NULL DEFAULT NULL,
  `purchase_price` decimal(10, 2) NULL DEFAULT NULL,
  `task_assistant_price` decimal(10, 2) NULL DEFAULT NULL,
  `gift_pack_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '礼品代发平台加价(元,叠加在上游仓库/礼品价格上;NULL/0=不加价)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

