-- ----------------------------
-- Table structure for taobao_query_rule
-- ----------------------------
DROP TABLE IF EXISTS `taobao_query_rule`;
CREATE TABLE `taobao_query_rule`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则级别:system=全局 / business=商家级',
  `taobao_taoling` int NULL DEFAULT 0 COMMENT '淘龄下限(年),低于拦截;0=不校验',
  `taobao_fox` int NULL DEFAULT 0 COMMENT '狐狸号:1=校验(cheater=1 拦截);0=不校验',
  `taobao_jiang_num` int NULL DEFAULT 0 COMMENT '降权次数阈值,>=该值拦截;0=不校验',
  `taobao_yun_black` int NULL DEFAULT 0 COMMENT '云黑数阈值,>=该值拦截;0=不校验',
  `taobao_heart` int NULL DEFAULT 0 COMMENT '心号下限值;0=不校验',
  `taobao_heart_unit` int NULL DEFAULT 0 COMMENT '心号单位值(0=心 1=钻 2=冠,与 heart 组合算下限)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '旺旺验号拦截规则(system/business 双级)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of taobao_query_rule
-- ----------------------------

-- ----------------------------
-- Table structure for task
